package net.minecraft.nbt;import java.util.*;public class CompoundTag implements Tag{public Map<String,Object>m=new HashMap<>();public Tag put(String k,Tag v){return (Tag)m.put(k,v);}public void putString(String k,String v){m.put(k,v);}public String getString(String k){return (String)m.getOrDefault(k,"");}public void putInt(String k,int v){m.put(k,v);}public int getInt(String k){return ((Number)m.getOrDefault(k,0)).intValue();}public void putLong(String k,long v){m.put(k,v);}public void putDouble(String k,double v){m.put(k,v);}public void putBoolean(String k,boolean v){m.put(k,v);}public boolean getBoolean(String k){return Boolean.TRUE.equals(m.get(k));}public void putUUID(String k,UUID v){m.put(k,v);}public UUID getUUID(String k){return (UUID)m.get(k);}public boolean contains(String k){return m.containsKey(k);}public CompoundTag getCompound(String k){return (CompoundTag)m.getOrDefault(k,new CompoundTag());}public ListTag getList(String k,int type){return (ListTag)m.getOrDefault(k,new ListTag());}public CompoundTag copy(){CompoundTag n=new CompoundTag();for(var e:m.entrySet()){Object v=e.getValue();n.m.put(e.getKey(),v instanceof CompoundTag t?t.copy():v instanceof ListTag l?l.copy():v);}return n;}}